mapper.select:
SELECT alarm.alarmLevel, v.*, t.name as assetName, t.id as assetId, t.org_id as assetOrgId, t.row_index as rowIndex, t.COLUMN_INDEX as columnIndex, f.VIEW_URL FROM (select distinct c.id, c.name, c.row_index, c.COLUMN_INDEX, a.org_id, a.id as room_id from cabinet c, room a where a.id = c.room_id and a.id = #{orgId}) t left join TOPO_VERTEX v on v.asset_id = t.id and v.org_id = t.room_id left join FILE_RELATE f on t.id = f.ITEM_ID left join (SELECT c.ID id, MIN(i.ALARM_LEVEL) alarmLevel FROM CABINET c LEFT JOIN ROOM r ON c.ROOM_ID = r.ID LEFT JOIN ASSET_ATTACH a ON a.CABINET_ID = c.ID LEFT JOIN ALARM_INFO i ON a.ASSET_ID = i.ASSET_ID LEFT JOIN ASSET aa on aa.id = a.ASSET_ID WHERE (i.STATUS = 1 OR (i.STATUS = 2 AND i.ALARM_STATE = 1)) and i.BLANK = 1 AND r.ID = #{orgId}
and (aa.ASSET_SUPPLIER != 'JCCA' or aa.ASSET_SUPPLIER is null)
GROUP BY c.ID) alarm on t.id = alarm.id where t.room_id = #{orgId}

select p.asset_id, p.status, v.node_id from topo_asset_port p left join topo_vertex v on p.asset_id = v.asset_id and p.port_index = v.port_index left join asset a on a.id = p.asset_id where v.is_port = 1 and a.is_del = 1
and a.org_id in
#{orgId}
and p.status = #{params.status}

SELECT v.*, t.name as assetName,t.A_B_FLAG as aBFlag, t.id as assetId, t.org_id as assetOrgId, t.asset_mode as assetMode,t.watch, t.show_core, f.view_url FROM asset t left join TOPO_VERTEX v on t.id = v.asset_id and v.node_type = 'wan_topo' left join FILE_RELATE f on f.ITEM_ID = t.id where t.SHOW_TOPO = 1 and t.IS_DEL = 1 and t.asset_mode = 42 and t.id in
#{id}
order by t.name

mapper.delete:
delete from TOPO_VERTEX
where NODE_TYPE = #{nodeType}
  and ORG_ID = #{orgId}

delete from TOPO_VERTEX
where NODE_TYPE = #{nodeType}
  and CORE_ASSET_ID = #{assetId}
